1px solid #f0f2f6}.activity-item:last-child{border-bottom:0}.activity-icon{width:32px;height:32px;border-radius:9px;display:grid;place-items:center;flex-shrink:0;font-size:14px}.activity-text{flex:1;min-width:0}.activity-text b{font-size:11px;display:block;margin:2px 0 5px}.activity-text p{font-size:10px;color:var(--muted);margin:0}.activity-time{font-size:10px;color:#9aa4b5;white-space:nowrap;margin-top:3px}.table-panel{overflow:hidden}.table-tools{display:flex;align-items:center;gap:9px}.search{border:1px solid var(--line);border-radius:8px;padding:9px 11px;font-size:11px;min-width:190px;outline:none}.filter{border:1px solid var(--line);border-radius:8px;padding:9px;background:white;color:#647187;font-size:11px}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;white-space:nowrap}th{text-align:left;background:#fbfcfe;color:#8b96a8;font-size:10px;text-transform:uppercase;letter-spacing:.65px;padding:13px 20px;font-weight:800}td{padding:15px 20px;border-top:1px solid #eff2f6;font-size:11px}tbody tr:hover{background:#fbfdff}.medicine{display:flex;align-items:center;gap:10px}.med-icon{width:34px;height:34px;background:#f0f4fb;border-radius:9px;display:grid;place-items:center;font-size:17px}.medicine b{font-size:11px;display:block}.medicine small{font-size:10px;color:var(--muted);display:block;margin-top:4px}.stock{font-weight:800}.stock-low{color:var(--red)}.stock-ok{color:#218f73}.status{display:inline-flex;align-items:center;gap:5px;padding:5px 8px;border-radius:20px;font-size:10px;font-weight:750}.status:before{content:"";width:5px;height:5px;border-radius:50%;background:currentColor}.status.ok{background:#eaf8f2;color:#218f73}.status.low{background:#fff0ed;color:#d15d43}.status.exp{background:#fff5df;color:#b9801a}.bottom-note{font-size:10px;color:#929db0;margin-top:16px;display:flex;justify-content:space-between;gap:12px}
