    <div class="stat"><div class="stat-head">Units in stock <span class="stat-icon si-green">▦</span></div><h2 id="total-units">8,426</h2><div class="stat-foot">Across all recorded batches</div></div>
    <div class="stat"><div class="stat-head">Low-stock items <span class="stat-icon si-amber">⚑</span></div><h2 id="low-count">7</h2><div class="stat-foot"><span class="warn">Needs attention</span> · at reorder level</div></div>
    <div class="stat"><div class="stat-head">Near expiry <span class="stat-icon si-red">◷</span></div><h2 id="expiry-count">4</h2><div class="stat-foot">Review upcoming expiry dates</div></div>
  </section>
  <section class="grid-main">
