<div class="overlay" id="modal-overlay" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal">
  <div class="modal-head"><h2 id="modal-title">Receive stock</h2><button class="close" onclick="closeModal()" aria-label="Close">×</button></div><p id="modal-desc">Record incoming medicine to update the available inventory.</p>
  <form id="movement-form">
    <div class="field"><label for="med-select">Medicine</label><select id="med-select" required></select></div>
    <div class="field"><label for="qty-input">Quantity</label><input id="qty-input" type="number" min="1" step="1" required placeholder="Enter quantity"/></div>
    <div class="field" id="batch-field"><label for="batch-input">Batch number (optional demo field)</label><input id="batch-input" placeholder="e.g. BATCH-2026-014"/></div>
    <div class="modal-actions"><button class="btn secondary" type="button" onclick="closeModal()">Cancel</button><button class="btn primary" id="submit-movement" type="submit">Record stock in</button></div>
  </form>
