<div class="toast" id="toast"></div>
<script>
const medicines=[
{id:1,name:"Paracetamol 500 mg",generic:"Paracetamol",barcode:"4800012345678",batch:"PCM-2405",expiry:"2027-05",qty:1240,reorder:200,unit:"tablets",icon:"💊"},
{id:2,name:"Amoxicillin 500 mg",generic:"Amoxicillin",barcode:"4800012345685",batch:"AMX-2311",expiry:"2027-11",qty:86,reorder:100,unit:"capsules",icon:"💊"},
{id:3,name:"Cetirizine 10 mg",generic:"Cetirizine",barcode:"4800012345692",batch:"CTZ-2402",expiry:"2027-02",qty:420,reorder:80,unit:"tablets",icon:"💠"},
{id:4,name:"Salbutamol nebules",generic:"Salbutamol",barcode:"4800012345708",batch:"SAL-2601",expiry:"2026-12",qty:24,reorder:50,unit:"nebules",icon:"🧪"},
{id:5,name:"Oral rehydration salts",generic:"ORS",barcode:"4800012345715",batch:"ORS-2508",expiry:"2027-08",qty:350,reorder:60,unit:"sachets",icon:"🧃"},
{id:6,name:"Ibuprofen 200 mg",generic:"Ibuprofen",barcode:"4800012345722",batch:"IBU-2603",expiry:"2028-03",qty:210,reorder:75,unit:"tablets",icon:"💊"},
{id:7,name:"Vitamin C 500 mg",generic:"Ascorbic acid",barcode:"4800012345739",batch:"VTC-2509",expiry:"2026-11",qty:42,reorder:80,unit:"tablets",icon:"🍊"}
];
let movementType="in";
const fmt=n=>n.toLocaleString("en-PH");
function renderTable(){const q=document.getElementById('search-input').value.toLowerCase();const filter=document.getElementById('status-filter').value;const list=medicines.filter(m=>(m.name.toLowerCase().includes(q)||m.barcode.includes(q)||m.generic.toLowerCase().includes(q))&&(filter==='all'||(filter==='low'?m.qty<=m.reorder:m.qty>m.reorder)));document.getElementById('inventory-body').innerHTML=list.map(m=>{const low=m.qty<=m.reorder;const near=m.expiry<"2027-01";return `<tr><td><div class="medicine"><div class="med-icon">${m.icon}</div><div><b>${m.name}</b><small>${m.generic}</small></div></div></td><td>${m.barcode}</td><td>${m.batch}<br><small style="color:var(--muted)">Exp. ${m.expiry}</small></td><td><span class="stock ${low?'stock-low':'stock-ok'}">${fmt(m.qty)} ${m.unit}</span></td><td>${m.reorder} ${m.unit}</td><td><span class="status ${low?'low':near?'exp':'ok'}">${low?'Low stock':near?'Check expiry':'In stock'}</span></td><td><button class="link-btn" onclick="quickMedicine(${m.id})">Record ↗</button></td></tr>`}).join('')||'<tr><td colspan="7" style="text-align:center;color:#8b96a8;padding:28px">No matching medicines found.</td></tr>';document.getElementById('low-count').textContent=medicines.filter(m=>m.qty<=m.reorder).length;document.getElementById('total-units').textContent=fmt(medicines.reduce((a,m)=>a+m.qty,0));document.getElementById('total-types').textContent=medicines.length;document.getElementById('expiry-count').textContent=medicines.filter(m=>m.expiry<"2027-01").length;}
function fillSelect(selected){document.getElementById('med-select').innerHTML=medicines.map(m=>`<option value="${m.id}" ${m.id===selected?'selected':''}>${m.name} — ${m.barcode}</option>`).join('')}
function openModal(type,medId){movementType=type;document.getElementById('modal-title').textContent=type==='in'?'Receive stock':'Record stock out';document.getElementById('modal-desc').textContent=type==='in'?'Record incoming medicine to increase available inventory.':'Record medicine dispensed or issued to decrease available inventory.';document.getElementById('submit-movement').textContent=type==='in'?'Record stock in':'Record stock out';fillSelect(medId||medicines[0].id);document.getElementById('qty-input').value='';document.getElementById('batch-input').value='';document.getElementById('modal-overlay').classList.add('show');setTimeout(()=>document.getElementById('qty-input').focus(),100)}
function closeModal(){document.getElementById('modal-overlay').classList.remove('show')}
function quickMedicine(id){openModal('in',id)}
function showToast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.remove('show');void t.offsetWidth;t.classList.add('show')}
function addActivity(m,type,qty){const item=document.createElement('div');item.className='activity-item';item.innerHTML=`<div class="activity-icon ${type==='in'?'si-green':'si-blue'}">${type==='in'?'↙':'↗'}</div><div class="activity-text"><b>${m.name}</b><p>Stock ${type==='in'?'received':'issued'} · ${type==='in'?'+':'−'}${qty} ${m.unit}</p></div><div class="activity-time">Just now</div>`;document.getElementById('activity-list').prepend(item)}
document.getElementById('movement-form').addEventListener('submit',e=>{e.preventDefault();const id=Number(document.getElementById('med-select').value);const qty=Number(document.getElementById('qty-input').value);const m=medicines.find(x=>x.id===id);if(!m||!Number.isInteger(qty)||qty<1){showToast('Enter a valid whole-number quantity.');return}if(movementType==='out'&&qty>m.qty){showToast('Not enough stock available for this issue.');return}m.qty+=movementType==='in'?qty:-qty;const batch=document.getElementById('batch-input').value.trim();if(movementType==='in'&&batch)m.batch=batch;addActivity(m,movementType,qty);renderTable();closeModal();showToast(`Stock ${movementType==='in'?'received':'issued'} successfully · ${m.name}`);document.getElementById('barcode-input').value='';});
document.getElementById('scan-form').addEventListener('submit',e=>{e.preventDefault();const value=document.getElementById('barcode-input').value.trim();if(!value){showToast('Scan or enter a barcode first.');return}const m=medicines.find(x=>x.barcode===value);if(m){fillSelect(m.id);showToast(`Found: ${m.name} · ${fmt(m.qty)} ${m.unit} available`);openModal('in',m.id)}else{showToast('Barcode not found in this demo catalog. Add the medicine first.')}});
document.getElementById('search-input').addEventListener('input',renderTable);document.getElementById('status-filter').addEventListener('change',renderTable);
document.getElementById('modal-overlay').addEventListener('click',e=>{if(e.target.id==='modal-overlay')closeModal()});
function navigate(page){document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.getElementById('crumb').textContent=page;document.getElementById('page-title').textContent=page==='Dashboard'?'Inventory overview':page; if(page==='Stock In')openModal('in');else if(page==='Stock Out')openModal('out');else if(page==='Inventory'){document.getElementById('search-input').focus();document.querySelector('.table-panel').scrollIntoView({behavior:'smooth',block:'start'})}else if(page==='Transactions'){document.querySelector('.grid-main').scrollIntoView({behavior:'smooth',block:'start'})}else if(page==='Reports')showToast('Demo report: use Export CSV to download the current inventory.');else if(page==='Suppliers'||page==='Settings')showToast(`${page} is a placeholder in this website model.`)}
document.querySelectorAll('.nav button').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.page)));
function exportCsv(){const rows=[['Medicine','Generic name','Barcode','Batch','Expiry','Quantity','Unit','Reorder level','Status'],...medicines.map(m=>[m.name,m.generic,m.barcode,m.batch,m.expiry,m.qty,m.unit,m.reorder,m.qty<=m.reorder?'Low stock':'In stock'])];const csv=rows.map(r=>r.map(v=>`"${String(v).replace(/"/g,'""')}"`).join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));a.download='carestock-inventory.csv';a.click();URL.revokeObjectURL(a.href);showToast('Inventory CSV exported.')}
renderTable();
</script>
</body>
</html>